// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address actor, address implA) public {
        vm.assume(actor != address(0));
        vm.assume(implA != address(0));

        // actor becomes owner/initializer
        vm.prank(actor);
        c.initialize();

        // set a valid implementation first
        vm.prank(actor);
        c.updateRoundImplementation(payable(implA));

        // an update attempt with the zero address must fail and must NOT change state
        vm.prank(actor);
        bool ok;
        try c.updateRoundImplementation(payable(address(0))) {
            ok = true;
        } catch {
            ok = false;
        }

        // general rule: a rejected update is atomic — the zero-address update never
        // succeeds AND roundImplementation still equals the last accepted implementation
        assertTrue(!ok && c.roundImplementation() == implA);
    }
}
